import pandas as pd
import itertools
import numpy as np

def task_func(animals=None, foods=None):
    default_animals = ['Dog', 'Cat', 'Elephant', 'Tiger', 'Lion', 'Zebra', 'Giraffe', 'Bear', 'Monkey', 'Kangaroo']
    default_foods = ['Meat', 'Fish', 'Grass', 'Fruits', 'Insects', 'Seeds', 'Leaves']

    animals_missing = animals is None or len(animals) == 0
    foods_missing = foods is None or len(foods) == 0

    if animals_missing and foods_missing:
        return pd.DataFrame()

    if animals_missing:
        animals = default_animals
    if foods_missing:
        foods = default_foods

    pairs = [f'{animal}:{food}' for animal, food in itertools.product(animals, foods)]
    np.random.shuffle(pairs)

    data = np.array(pairs).reshape(len(animals), len(foods))
    return pd.DataFrame(data, index=animals, columns=foods)
